from pathlib import Path
import sys, base64, io, tarfile, hashlib

root = Path(sys.argv[1] if len(sys.argv)>1 else 'debt-app')
PAYLOAD = '''[... ELLIPSIZATION ...]^...'''

data = base64.b64decode(PAYLOAD)
sha = hashlib.sha256(data).hexdigest()
expected='cb2605e2766f0f4dfa3a53ff7a6dfd4d0637d7c39906705187427bbae39dd55b'
if sha != expected:
    raise SystemExit(f'v110 payload hash mismatch: {sha}')
with tarfile.open(fileobj=io.BytesIO(data), mode='r:gz') as tf:
    tf.extractall(root)
print('PATCH_V110_OK')
